INSERT INTO `blog_entry` VALUES (1927,'admin','Software Sensation has released version 2.5 of jWebApp','jwebapp, java, software sensation','Software Sensation Inc. Announces A Software Development Platform Named jWebApp That Is Reported To Make Web Application Development Far Simpler.GVFfegNpby1BRL4a9YyfZldcqWpvCmbhYnoZ34H1IFBaNOg5X4nTVsmIdjUk','software_sensation_has_released_version_25_of_jwebapp','http://www.jwebapp.org',742,7,0,'false','false','false','2006-05-20 17:42:10','2025-10-09 15:33:32','2006-05-17 16:42:10'),(1928,'admin','Introducing jPersist','jpersist, java, software sensation','Zaproxy alias impedit expedita quisquam pariatur exercitationem. Nemo rerum eveniet dolores rem quia dignissimos.','introducing_jpersist','http://www.jpersist.org',251,2,0,'true','true','true','2025-10-09 15:33:32','2025-10-09 15:33:32','2007-07-24 06:06:20'),(1929,'admin','Introducing jWebApp','jwebapp, framework, web development, java, software sensation','jWebApp is a Model-View-Controller framework that is simple and straight forward and doesn&#8217;t try to be all things. In fact, jWebApp is specifically designed to satisfy the need for simpler web development.yRODhCBjgPbrY2fxgNk07PQU6BicbFTlU4621PS59dB1VEa0hpKLYAruv7GB','introducing_jwebapp','http://www.jwebapp.org',263,2,0,'false','false','false','2025-10-09 15:33:32','2025-10-09 15:33:32','2007-07-27 06:02:42'),(1930,'admin','jWebApp 4.5.0 Final Stable/Production Level Release is Available!','jwebapp, configuration free, MVC, scripting, validation, email, online payments, regexp, java, software sensation','This release marks the final changes for a stable/production release. A ton of testing has taken place and all supported platforms have been tested. jWebApp is now \r\nproduction ready and moving from beta to final release.hWbZx0oVvCnvpYCc7QxjtdIZXmNhV4nw03yrx6MOfH4Qm3hsDrgfRtxEvpJ6PUYl2boInFZcb0C8LzQP','jwebapp_450_final_stableproduction_level_release_is_available','http://www.jwebapp.org',1036,10,0,'false','false'